using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CooperationTalkTests
{
    static EntityId Person=>HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Ready(){var s=PrivateInspectionTests.Start();PrivateInspectionTests.Contact(s);return s;}
    static PrivateInspectionReply Talk(WorldSession s)=>s.ConsultPrivateInspection(Person,s.PlayerControl,s.Revision);
    static CommandResult Confirm(WorldSession s,PrivateInspectionReply r,string id="request:talk-confirm")=>s.ManageCompanion(new(new(id),Person,CompanionAction.PrivateInspect,r.Fee),s.PlayerControl,r.Revision);
    static void At(WorldSession s,long t)=>PersonalCompanionTests.Advance(s,t);
    [Fact]public void ConsultationDoesNotPayOrIssueAndReplyContainsOnlyPublicSpeech(){var s=Ready();var b=ContractJson.Write(s.DiagnosticSnapshot());var r=Talk(s);Assert.True(r.CanConfirm);Assert.Equal(20,r.Fee);Assert.Equal(s.Revision,r.Revision);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Contains("所属を離れる話ではありません",r.Speech);Assert.Equal(new[]{"Revision","CanConfirm","Fee","Speech"},typeof(PrivateInspectionReply).GetProperties().Select(p=>p.Name));}
    [Fact]public void UnwillingReplyDoesNotPublishHiddenReasonOrCharge(){var w=Ready().DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==Person?c with{WillObey=false}:c).ToArray();var s=new WorldSession(w);var b=ContractJson.Write(w);var r=Talk(s);Assert.False(r.CanConfirm);Assert.Equal("今回は引き受けられません。",r.Speech);Assert.DoesNotContain("忠誠",r.Speech);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Confirm(s,r).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void BusyPersonSaysOnlyThatExistingWorkMustFinish(){var s=Ready();Assert.Equal(ResultCode.Accepted,Confirm(s,Talk(s)).Code);var b=ContractJson.Write(s.DiagnosticSnapshot());var r=Talk(s);Assert.False(r.CanConfirm);Assert.Contains("手が離せません",r.Speech);Assert.DoesNotContain("request:",r.Speech);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));At(s,20);Assert.True(Talk(s).CanConfirm);}
    [Fact]public void UnpaidContactExplainsNextStepWithoutTakingMoney(){var s=PrivateInspectionTests.Start();At(s,8);var b=ContractJson.Write(s.DiagnosticSnapshot());var r=Talk(s);Assert.False(r.CanConfirm);Assert.Contains("精算",r.Speech);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(true)][InlineData(false)]public void RemoteReplyCannotRevealWhetherSourceWouldCooperate(bool willing){var s=Ready();Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:talk-away","suwa"),s.Revision).Code);At(s,s.Seconds+2);var w=s.DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==Person?c with{WillObey=willing}:c).ToArray();s=new WorldSession(w);var r=Talk(s);Assert.False(r.CanConfirm);Assert.Equal("本人に現地で会って相談してください。",r.Speech);}
    [Fact]public void AnotherActorCannotInspectPlayersLocalDialogue(){var s=Ready();var r=s.ConsultPrivateInspection(Person,Person,s.Revision);Assert.False(r.CanConfirm);Assert.Equal("状況が変わりました。もう一度相談してください。",r.Speech);}
    [Fact]public void ChangedWorldRequiresNewConsultationBeforePayment(){var s=Ready();var r=Talk(s);s.SetPaused(false);s.SetPaused(true);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.StateChanged,Confirm(s,r).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));r=Talk(s);Assert.Equal(ResultCode.Accepted,Confirm(s,r).Code);Assert.Equal(ResultCode.AlreadyAccepted,Confirm(s,r).Code);Assert.Equal(960,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void ActualSaveRestoresReplyAndSameFutureWork(){var s=Ready();s.SetPaused(true);var r=Talk(s);var loaded=Restore(s);Assert.Equal(r,Talk(loaded));Assert.Equal(ResultCode.Accepted,Confirm(s,r).Code);Assert.Equal(ResultCode.Accepted,Confirm(loaded,r).Code);At(s,20);At(loaded,20);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(loaded.DiagnosticSnapshot()));Assert.Equal(Talk(s),Talk(loaded));}
    [Fact]public void ActualSaveRetainsRefusalAndNoPayment(){var w=Ready().DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==Person?c with{WillObey=false}:c).ToArray();var s=new WorldSession(w);s.SetPaused(true);var loaded=Restore(s);Assert.Equal(Talk(s),Talk(loaded));Assert.False(Talk(loaded).CanConfirm);Assert.Equal(980,NewGameWork.Balance(loaded.DiagnosticSnapshot(),loaded.PlayerControl));}
    [Fact]public void AcceptedReplyIsNotSupportForLeavingMastersHouse(){var s=Ready();var b=s.DiagnosticSnapshot();Confirm(s,Talk(s));At(s,20);var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(b.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.Equal(ContractJson.Write(b.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(b.Offices),ContractJson.Write(w.Offices));Assert.False(s.CompanionView().Single(c=>c.Person==Person).Active);Assert.Empty(w.Units);}
    [Fact]public void OldPolicyDoesNotGainNewConsultation(){var s=PrivateInspectionTests.Start(false);PrivateInspectionTests.Contact(s);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.False(Talk(s).CanConfirm);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    static WorldSession Restore(WorldSession s){var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"cooperation-talk-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"talk",w.WorldId).Published);var host=new WorldSessionHost(PrivateInspectionTests.Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("talk"),host.Current,host.Current.Revision));return host.Current;}
}
